// Tokenize only the declarations generated by our bounded C++/Java formatters.
(() => {
  "use strict";
  function tokenize(declaration) {
    return (declaration.match(/"(?:\\[\s\S]|[^"\\])*"|'(?:\\[\s\S]|[^'\\])*'|[A-Za-z_]\w*|-?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?(?:LL|L|f)?|\s+|./g) ?? []).map(text => ({
      text,
      kind: /^["']/.test(text) ? "string" : /^(byte|short|int|long|double|float|bool|boolean|char|true|false|null|new|True|False|None)$/.test(text) ? "keyword" : /^(vector|string|String|Byte|Short|Integer|Long|Float|Double|Boolean|Character|List|ArrayList|Arrays)$/.test(text) ? "type" :
        /^-?\d/.test(text) ? "number" : /^[A-Za-z_]\w*$/.test(text) ? "variable" : "plain",
    }));
  }
  globalThis.LeetCase.highlight = Object.freeze({ tokenize });
})();
